import{_ as t,o,c as a,a3 as n}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Fix common Wake problems: start with wake doctor, then messages in the repository, on the server and from sign-in providers, and what to do.","frontmatter":{"description":"Fix common Wake problems: start with wake doctor, then messages in the repository, on the server and from sign-in providers, and what to do."},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md","lastUpdated":1794486787000}'),s={name:"reference/troubleshooting.md"};function r(i,e,d,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="start-with-wake-doctor" tabindex="-1">Start with wake doctor <a class="header-anchor" href="#start-with-wake-doctor" aria-label="Permalink to &quot;Start with wake doctor&quot;">​</a></h2><p>In the repository, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>It checks the connection, the plan method, the plan&#39;s text and detail, your login, the server&#39;s version, the MCP endpoint, <code>wake</code> on <code>PATH</code> and every connected agent&#39;s files. It changes nothing, and ends each failed check with its fix, such as <code>Fix: wake login --server &lt;your Wake URL&gt;</code>. On the machine where you installed Wake, plain <code>wake login</code> finds your Wake URL by itself.</p><p>On the machine that hosts Wake, <code>wake-server status</code> shows the version, each service&#39;s health and whether Docker runs; see <a href="/wake-dist/docs/run/status">Status</a>.</p><h2 id="in-the-repository" tabindex="-1">In the repository <a class="header-anchor" href="#in-the-repository" aria-label="Permalink to &quot;In the repository&quot;">​</a></h2><p><strong>The session starts with one <code>Wake:</code> line.</strong> Wake is offline, the token is invalid, or you are not logged in. The line says which, and what to run.</p><p><strong><code>Wake: not logged in to &lt;your Wake URL&gt; (workspace &lt;id&gt;); run `wake login --server &lt;your Wake URL&gt; --workspace &lt;id&gt;`, then start a new session.</code></strong> This machine has no login for the repository&#39;s workspace, for example when you join a teammate&#39;s project. Run the command the line names, then start a new session. <code>&lt;id&gt;</code> is the <code>workspaceId</code> in the repository&#39;s <code>.wake/config.json</code>.</p><p><strong><code>wake: the token is invalid, expired or revoked; create one in Wake and run `wake login`</code>.</strong> Run <code>wake login</code> again. At a session start the same problem reads <code>Wake: the token for &lt;your Wake URL&gt; is invalid, expired or revoked; run `wake login --server &lt;your Wake URL&gt;`.</code> A token stops working when it expires, is revoked, or when you <a href="/wake-dist/docs/use/account#sign-out-everywhere">sign out everywhere</a>.</p><p><strong><code>! Plan text: 2 tasks shortened to fit Wake&#39;s limits; the full text stays in the repository</code>.</strong> Some tasks have text longer than Wake keeps (<a href="/wake-dist/docs/agents/milestones#long-task-text">Long task text</a>). <code>wake doctor</code> lists each one under the warning, with its file, line and field (<code>title</code>, <code>description</code> or <code>done when</code>). It is a warning, not a failure: <code>wake sync</code> still sends the plan, and says so until you shorten those lines.</p><p><strong>A task&#39;s Includes and Done when say &quot;The plan does not say…&quot;.</strong> The task has no indented lines under it in its plan file. <code>wake doctor</code> warns with <code>! Plan detail: 3 open tasks without a &quot;Done when:&quot; line; add one under each task in its plan file</code> and lists each one as <code>path:line</code>. Add a description line and a <code>Done when:</code> line under each task (see <a href="/wake-dist/docs/agents/openspec">OpenSpec</a>, <a href="/wake-dist/docs/agents/spec-kit">Spec Kit</a> or <a href="/wake-dist/docs/agents/odd">ODD</a>), or ask your agent to add them to every open task, then run <code>wake sync</code>. Done tasks and ODD table rows are never listed.</p><p><strong>The CLI and the server versions differ.</strong> <code>wake login</code>, <code>init</code>, <code>sync</code>, <code>watch</code> and the session context end with one line, and the command still works:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wake: wake 2.4.1 is available for this server (you have 2.4.0); run `wake upgrade`</span></span>\n<span class="line"><span>wake: this server needs wake 2.4.0 or newer (you have 2.3.0); run `wake upgrade`</span></span>\n<span class="line"><span>wake: wake 2.5.0 is newer than this server (2.4.0); upgrade the server or run `wake upgrade --version 2.4.0`</span></span></code></pre></div><p>Wake checks each server at most once an hour, and stays silent when the server does not answer.</p><p><strong><code>wake: wake 2.4.1 is available (you have 2.4.0); run `wake upgrade`</code>.</strong> A newer CLI is released. Without a server recommendation, <code>login</code>, <code>init</code>, <code>sync</code> and <code>watch</code> ask GitHub for the newest release at most once a day. Set <code>WAKE_NO_UPDATE_CHECK=1</code> to turn it off; it is off when <code>CI</code> is set.</p><p><strong><code>wake: project shop-api is archived; restore it in the web app to sync again</code>.</strong> Someone archived the project. Restore it from <strong>Archived projects</strong> in the web app&#39;s project switcher; <code>wake init</code> and <code>wake setup</code> refuse an archived project the same way.</p><p><strong><code>wake: you are a viewer in this workspace, which is read-only; ask an owner to make you a member</code>.</strong> Viewers read everything and change nothing; see <a href="/wake-dist/docs/use/workspaces#roles">Roles</a>.</p><h2 id="on-the-server" tabindex="-1">On the server <a class="header-anchor" href="#on-the-server" aria-label="Permalink to &quot;On the server&quot;">​</a></h2><p>The installer&#39;s own messages start with <code>wake:</code>, like the CLI&#39;s, and <code>wake-server</code>&#39;s with <code>wake-server:</code>; each names what failed and what to run next. A <code>wake:</code> line printed while the install command runs comes from the installer.</p><p><strong>The installer stops on a busy port.</strong> Pass other ports with <code>--port</code> and <code>--s3-port</code>; see <a href="/wake-dist/docs/run/install-options#options">Install options</a>.</p><p><strong><code>wake: Wake is already installed in &lt;dir&gt;: run the installer with --dir &lt;dir&gt; to see it, or remove that installation first</code>.</strong> One machine keeps one Wake server, and another directory already holds it. Run the installer with <code>--dir</code> set to that directory, or remove that installation first.</p><p><strong><code>ssh-keygen from OpenSSH 8.1 or newer is needed to verify Wake releases: install it (the openssh-client package on Linux), then ...</code>.</strong> The installer, <code>wake-server upgrade</code> and <code>wake-server install-cli</code> verify each release&#39;s signature with <code>ssh-keygen</code>. Install it, then run the command the line names again.</p><p><strong><code>wake-server: command not found</code>.</strong> The installer put <code>wake-server</code> in <code>~/.local/bin</code>, which is not on your <code>PATH</code>, or you are not the user who installed Wake. Run it as that user, never with <code>sudo</code>. Add <code>export PATH=&quot;$HOME/.local/bin:$PATH&quot;</code> to your shell profile (<code>~/.zshrc</code>, <code>~/.bashrc</code> or <code>~/.profile</code>) and open a new terminal, or run <code>&lt;your installation directory&gt;/wake-server</code>.</p><p><strong><code>wake-server: an upgrade, backup or restore is running (process &lt;pid&gt;): try again when it finishes, or remove &lt;dir&gt;/.lock if no wake-server command runs</code>.</strong> Only one of them runs at a time, and <code>start</code> and <code>stop</code> do not run meanwhile either. Run the command again when the other finishes. Remove the <code>.lock</code> directory only when no <code>wake-server</code> command runs, for example after the machine stopped in the middle of one.</p><p><strong><code>wake-server: not enough free disk for the backup: it needs about &lt;n&gt; MB in &lt;dir&gt;/backups, &lt;m&gt; MB are free</code>.</strong> A backup, upgrade or restore stopped before changing anything: the disk holding <code>backups/</code> is too full. Move older backups off the machine and delete them, or free other space on that disk, then run it again; see <a href="/wake-dist/docs/run/backup#free-disk-first">Free disk first</a>.</p><p><strong>Wake does not answer after a reboot.</strong> Docker is not running. Run <code>wake-server start</code>; on Linux, start Docker first. To have it come back by itself, see <a href="/wake-dist/docs/run/start-stop#come-back-after-a-reboot">Come back after a reboot</a>.</p><p><strong>A domain installation exits <code>1</code> naming DNS and ports 80 and 443.</strong> The names do not point at the machine yet, or the ports are closed. The stack keeps running and gets its certificates once DNS is right; see <a href="/wake-dist/docs/run/install-options#install-on-a-domain">Install on a domain</a>.</p><p><strong>An upgrade says it rolled back.</strong> The new version was not healthy in time, so the previous one runs again with its data. Check the <a href="/wake-dist/docs/run/logs">logs</a>, and see <a href="/wake-dist/docs/run/upgrade">Upgrade</a>.</p><p><strong>An upgrade that runs by itself failed.</strong> Nothing prints it; read its log. The server&#39;s daily upgrade writes <code>auto-upgrade.log</code> in your installation directory, and the CLI&#39;s upgrade at an agent session start writes <code>~/.config/wake/auto-upgrade.log</code> on that machine. See <a href="/wake-dist/docs/run/logs#upgrade-logs">Upgrade logs</a>.</p><p><strong>Evidence uploads answer <code>evidence_storage_unavailable</code>.</strong> The server has no evidence storage, or cannot reach it. An installation sets it up; a server you run yourself needs the <a href="/wake-dist/docs/reference/environment#evidence-storage">evidence storage variables</a>.</p><p><strong>A sign-up answers <code>people_limit_reached</code>.</strong> The installation already has the free plan&#39;s 3 people. Free a place with <code>wake-server accounts disable &lt;email&gt;</code>; see <a href="/wake-dist/docs/run/sign-up#free-plan-accounts">Free plan accounts</a>.</p><p><strong>A sign-up answers <code>sign_up_closed</code>.</strong> Sign-up needs an invitation on this server; ask an owner for an <a href="/wake-dist/docs/use/workspaces#invite-people">invitation link</a>.</p><p><strong>Someone reports an <code>Internal error (request id req_...)</code>.</strong> Find the request in the server&#39;s logs by that id; see <a href="/wake-dist/docs/run/logs#find-a-request-by-its-id">Find a request by its id</a>.</p><h2 id="sign-in-provider-errors" tabindex="-1">Sign-in provider errors <a class="header-anchor" href="#sign-in-provider-errors" aria-label="Permalink to &quot;Sign-in provider errors&quot;">​</a></h2><p>When a provider sign-in or a link from <strong>Account</strong> fails, the browser goes back to the screen it started from and shows one of these messages; <code>GitHub</code> stands for the provider. Starting the sign-in again is always safe. See <a href="/wake-dist/docs/run/sign-in-providers">Sign-in providers</a>.</p><table tabindex="0"><thead><tr><th>The person reads</th><th>Code</th><th>Why, and what to do</th></tr></thead><tbody><tr><td>This email already has a Wake account. Sign in with your password, then connect GitHub from Account.</td><td><code>account_exists_sign_in_with_password</code></td><td>The provider account&#39;s email belongs to a Wake user with a password. Wake never links by email: they sign in with the password and link the provider from <strong>Account</strong></td></tr><tr><td>This email belongs to another Wake account. Sign in to it another way, then connect GitHub from Account.</td><td><code>email_taken</code></td><td>The email belongs to a Wake user who signs in with another provider</td></tr><tr><td>GitHub didn&#39;t confirm that this email is yours. Sign in another way, then connect GitHub from Account.</td><td><code>provider_email_unverified</code></td><td>A new account&#39;s email is missing or not verified by the provider. For Microsoft work accounts, add the <code>xms_edov</code> optional claim; see <a href="/wake-dist/docs/run/sign-in-providers#microsoft">Microsoft</a></td></tr><tr><td>Signing in with GitHub didn&#39;t work. Try again, or sign in another way.</td><td><code>provider_sign_in_failed</code></td><td>The provider refused the code, or its ID token failed a check</td></tr><tr><td>GitHub can&#39;t be reached right now. Try again, or sign in another way.</td><td><code>provider_unavailable</code></td><td>The provider&#39;s discovery document, keys or token endpoint failed, answered something unusable, or took more than 10 seconds. The server logs <code>sign-in provider unavailable</code> with the provider</td></tr><tr><td>This GitHub account is already connected to another Wake user.</td><td><code>provider_already_linked</code></td><td>A link chose a provider account another Wake user already linked</td></tr><tr><td>Another GitHub account is already connected to yours. Disconnect it first.</td><td><code>provider_link_conflict</code></td><td>A link chose a second account of a provider the user already linked</td></tr><tr><td>This is your only way to sign in. Connect another method first.</td><td><code>last_sign_in_method</code></td><td>Unlinking the user&#39;s only way to sign in is refused</td></tr><tr><td>Accounts on this server are created from an invitation link. Ask someone in a workspace to invite you.</td><td><code>sign_up_closed</code></td><td>Only invitations sign up on this server; see <a href="/wake-dist/docs/run/sign-up">Sign-up and accounts</a></td></tr><tr><td>This invitation link is wrong, has expired, was revoked or was already used.</td><td><code>invitation_not_found</code></td><td>The invitation was revoked or used before the sign-in finished; ask for a new one</td></tr><tr><td>This installation already has the 3 people the free plan allows. The person who runs it can free a place by disabling an account.</td><td><code>people_limit_reached</code></td><td>A new account past the free plan&#39;s 3 people; see <a href="/wake-dist/docs/run/sign-up#free-plan-accounts">Free plan accounts</a></td></tr><tr><td>Something went wrong. Try again.</td><td><code>rate_limited</code></td><td>More than 30 sign-in attempts a minute from one address, or 10 new accounts an hour; wait a while and try again</td></tr></tbody></table><p>A sign-in whose state is missing or does not match, such as one opened from an old tab, answers <code>400</code> <code>invalid_oauth_state</code>; start it again. The routes of a provider that is not configured answer <code>404</code> <code>not_found</code>.</p>',38)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
